for k in range(NumSourceDestPairs):
    src, dst = SourceDestPairs[k]
    for n in range(NumNodes):
        inflow = quicksum(Flow[k, j, n] for j in range(NumNodes))
        outflow = quicksum(Flow[k, n, j] for j in range(NumNodes))
        if n == src:
            model.addConstr(inflow - outflow == -SourceData[k], name=f"FlowCons_{k}_{n}")
        elif n == dst:
            model.addConstr(inflow - outflow == SourceData[k], name=f"FlowCons_{k}_{n}")
        else:
            model.addConstr(inflow - outflow == 0, name=f"FlowCons_{k}_{n}")
